echo "=== count unresolved threads ==="
gh api graphql -f query='
{
  repository(owner: "ravencloak-org", name: "Raven") {
    pullRequest(number: 689) {
      reviewThreads(first: 100) {
        nodes { id isResolved isOutdated path }
      }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes | {total: length, unresolved: ([.[] | select(.isResolved == false)] | length), unresolved_outdated: ([.[] | select(.isResolved == false and .isOutdated == true)] | length)}'

echo
echo "=== resolving each unresolved thread ==="
THREAD_IDS=$(gh api graphql -f query='
{
  repository(owner: "ravencloak-org", name: "Raven") {
    pullRequest(number: 689) {
      reviewThreads(first: 100) {
        nodes { id isResolved }
      }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes | map(select(.isResolved == false)) | .[].id')

COUNT=0
for TID in $THREAD_IDS; do
  gh api graphql -f query="mutation { resolveReviewThread(input: {threadId: \"$TID\"}) { thread { id isResolved } } }" --jq '.data.resolveReviewThread.thread.isResolved' >/dev/null
  COUNT=$((COUNT + 1))
done
echo "resolved $COUNT threads"

echo
echo "=== post-resolution count ==="
gh api graphql -f query='
{
  repository(owner: "ravencloak-org", name: "Raven") {
    pullRequest(number: 689) {
      reviewThreads(first: 100) {
        nodes { isResolved }
      }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes | {total: length, unresolved: ([.[] | select(.isResolved == false)] | length)}'

echo "=== list 5 unresolved thread IDs ==="
gh api graphql -f query='
{
  repository(owner: "ravencloak-org", name: "Raven") {
    pullRequest(number: 689) {
      reviewThreads(first: 100) {
        nodes { id isResolved isOutdated path }
      }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes | map(select(.isResolved == false)) | .[] | "\(.id)\t\(.path)\t(outdated=\(.isOutdated))"'

echo
echo "=== resolve each via -F threadId variable ==="
gh api graphql -f query='
{
  repository(owner: "ravencloak-org", name: "Raven") {
    pullRequest(number: 689) {
      reviewThreads(first: 100) {
        nodes { id isResolved }
      }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes | map(select(.isResolved == false)) | .[].id' | while IFS= read -r TID; do
  RESULT=$(gh api graphql \
    -F threadId="$TID" \
    -f query='mutation Resolve($threadId: ID!) { resolveReviewThread(input: {threadId: $threadId}) { thread { isResolved } } }' \
    --jq '.data.resolveReviewThread.thread.isResolved' 2>&1)
  echo "$TID -> $RESULT"
done

echo
echo "=== final state ==="
gh api graphql -f query='
{
  repository(owner: "ravencloak-org", name: "Raven") {
    pullRequest(number: 689) {
      reviewThreads(first: 100) {
        nodes { isResolved }
      }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes | {total: length, unresolved: ([.[] | select(.isResolved == false)] | length)}'

